import pandas as pd

def suspicious_bank_accounts(accounts: pd.DataFrame, transactions: pd.DataFrame) -> pd.DataFrame:
    credited = transactions[transactions["type"] == "Credited"].copy()
    credited["ym"] = pd.to_datetime(credited["day"]).dt.to_period("M")
    agg = credited.groupby(["account_id", "ym"])["amount"].sum().reset_index()
    merged = agg.merge(accounts, on="account_id")
    susp = merged[merged["amount"] > merged["max_income"]].sort_values(["account_id", "ym"])

    susp_accs = set()
    for aid, grp in susp.groupby("account_id"):
        periods = list(grp["ym"])
        for i in range(1, len(periods)):
            if periods[i] - periods[i - 1] == 1:
                susp_accs.add(aid)
                break
    return pd.DataFrame({"account_id": sorted(list(susp_accs))})
